import json,re,glob,os,sys,collections
sys.path.insert(0,'/tmp/an')
from ans import final,base
from vis import listed
cid=sys.argv[1]
T=[l for l in open(f'/tmp/an/{cid}_truth.txt').read().split('\n') if l]
L=listed(cid)
def norm(p): return p[8:] if p.startswith('src/app/') else p
def folder(p):
    if p.endswith('/'): return p.rstrip('/')
    return os.path.dirname(p) if re.search(r'\.[A-Za-z0-9]+$',os.path.basename(p)) else p
def seg(p,n): return '/'.join(p.split('/')[:n])
def short(p): return p.replace('main/features/score-types/','F:')
res={}
for arm in ('plugin','bare'):
  for i in (1,2,3):
    txt,paths,mm=final(cid,arm,i)
    raw=sorted(set(folder(p) for p in paths)); n=[norm(r) for r in raw]
    prefixed=any(r.startswith('src/app/') for r in raw)
    mc=collections.Counter(); md={}
    for t in mm['missed']:
        anc=any(t.startswith(x+'/') for x in n)
        exact=any(x==t or x.startswith(t+'/') for x in n)
        if prefixed and exact: c='path-prefix'
        elif t not in L: c='not-in-context'+('(parent named)' if anc else '(no ancestor named)')
        elif anc: c='parent-not-child'
        else: c='usage-hop'
        mc[c]+=1; md[t]=c
    ec=collections.Counter(); ed={}
    for E in mm['extra']:
        e=norm(E)
        if any(t.startswith(e+'/') for t in T): c='broad-parent'
        elif re.search(r'/(services|models|constants|utils|shared)(/|$)',e) and not any(t.startswith(e) for t in T): c='support-folder'
        elif not any(seg(t,4)==seg(e,4) and seg(t,2)==seg(e,2) for t in T): c='wrong-module/other-module'
        else: c='other(same-slice sibling)'
        if prefixed and any(x==norm(E) for x in n) and any(norm(E)==t or norm(E).startswith(t+'/') for t in T): c='path-prefix (right folder, invalid prefix)'
        ec[c]+=1; ed[E]=c
    res[(arm,i)]=(mm,mc,md,ec,ed,prefixed,raw)
    print(arm,i,'R%.3f P%.3f F1 %.3f'%(mm['recall'],mm['precision'],mm['f1']),'missed',dict(mc),'extra',dict(ec),'prefixed' if prefixed else '')
# bare found / plugin missed
for t in T:
    bf=[i for i in (1,2,3) if t not in res[('bare',i)][0]['missed']]
    pf=[i for i in (1,2,3) if t not in res[('plugin',i)][0]['missed']]
    if bf and len(pf)<len(bf): print('BARE>PLUGIN',short(t),'bare runs',bf,'plugin runs',pf,'L' if t in L else 'NOTLISTED')
import pickle; pickle.dump(res,open(f'/tmp/an/{cid}_res.pkl','wb'))
EOF
