import json, collections, sys
raw = json.load(open('/tmp/nav/raw.json'))
P = 'main/features/score-types/'
def short(f): return ('F:' + f[len(P):]) if f.startswith(P) else f

MC = ['path-prefix', 'parent-not-child', 'listed-but-unread', 'not-in-context', 'usage-hop', 'wrong-module', 'other']
XC = ['broad-parent', 'support-folder', 'wrong-module/sibling', 'note-path/invented', 'other']

# ---------- plugin missed labels: (case, folder, run0) -> cause ----------
NIC6141 = set("""main/components/ui/tagged-metric
F:lm-carry/components/manual-override-wizard/effort
F:lm-lift/components/manual-override-wizard/effort
F:lm-lower/components/manual-override-wizard/effort
F:rsi/components/manual-override-wizard/effort
F:rula-reba/reba/components/manual-override-wizard/lower-arm
F:rula-reba/reba/components/manual-override-wizard/neck
F:rula-reba/reba/components/manual-override-wizard/trunk
F:rula-reba/rula/components/manual-override-wizard/lower-arm-position
F:rula-reba/rula/components/manual-override-wizard/neck
F:rula-reba/rula/components/manual-override-wizard/trunk
F:rula-reba/rula/components/manual-override-wizard/wrist-position
F:rula-reba/shared/components/display-card
F:rula-reba/shared/components/dotted-row""".split())
UH6141 = {'F:ge-adv/components/score-card/detail/shared/card-set-display', 'F:ge-adv/components/score-card/detail/shared/expandable-card-display',
          'F:ge-adv/components/wizard/shared/card-checkbox-set', 'F:ge-adv/components/wizard/shared/card-radio-button',
          'F:ge-adv/components/wizard/shared/expandable-card-checkbox'}

def plabel(case, f, r):
    f = short(f)
    if case == '438': return 'not-in-context'
    if case == '3571':
        if f.startswith('main/assets/'): return 'not-in-context'
        if f == 'main/components/dialogs/new-users-dialog': return 'not-in-context'  # author said parent-not-child; dialogs.md omits it (cf. 438, 6406)
        if f == 'main/screens/app/constants': return 'other'
        return 'usage-hop'
    if case == '5948':
        if 'ReportComponent' in f or 'components/tables' in f: return 'not-in-context'
        return 'listed-but-unread'
    if case == '5967':
        if r == 2 and f.startswith('F:nom/components/score-card'): return 'path-prefix'
        if f == 'F:ge-adv/components/score-card/detail': return 'usage-hop'
        if f == 'F:shared/providers': return 'not-in-context'
        return 'listed-but-unread'
    if case == '6086':
        if f in ('main/components/tables/report-table', 'main/screens/compare', 'main/screens/report/components/report-video'): return 'not-in-context'
        if f == 'main/components/ui/ReportDragDrop': return 'not-in-context' if r == 0 else 'parent-not-child'
        if f == 'main/screens/report/components/new-assessment-type-dialog': return 'listed-but-unread' if r == 0 else 'parent-not-child'
        return 'usage-hop'
    if case == '6141':
        if r == 0 and f in ('F:est/components/score-card/shared/cv-backed-metric', 'F:rula-reba/shared/models'): return 'path-prefix'
        if f in NIC6141: return 'not-in-context'
        if f in UH6141: return 'usage-hop'
        if f == 'main/components/inputs/cv-backed-form-field': return 'parent-not-child' if r == 2 else 'usage-hop'
        if f == 'F:est/components/score-card/shared/posture-scale-display': return 'parent-not-child' if r == 1 else 'usage-hop'
        return 'parent-not-child'
    if case == '6292':
        if r == 1 and f == 'F:shared/components/cycle-time-input': return 'path-prefix'
        if f in ('main/validators', 'F:rsi/components/manual-override-wizard/effort'): return 'not-in-context'
        return 'usage-hop'
    if case == '6404': return 'usage-hop'
    if case == '6406': return 'not-in-context' if f.endswith('new-users-dialog') else 'usage-hop'
    raise Exception(case)

# ---------- extras by cause per run (from per-case reports; 3571/5164/5967/5948/6086/6141 enumerated by hand) ----------
def X(**k): return k
XP = {  # plugin
 '438': [X(**{'broad-parent':1,'other':1}), X(**{'broad-parent':1,'other':2,'support-folder':2}), X(**{'broad-parent':1,'other':1})],
 '3571': [X(**{'broad-parent':1,'wrong-module/sibling':2,'other':1,'note-path/invented':1}),
          X(**{'broad-parent':1,'wrong-module/sibling':1,'other':2,'note-path/invented':1,'support-folder':1}),
          X(**{'broad-parent':1,'wrong-module/sibling':2,'other':1})],
 '5164': [X(**{'support-folder':4,'other':1,'note-path/invented':1}), X(**{'support-folder':7,'other':1,'wrong-module/sibling':1}), X(**{'support-folder':3,'other':1})],
 '5948': [X(**{'wrong-module/sibling':4,'support-folder':2}), X(**{'wrong-module/sibling':4,'support-folder':2}), X(**{'wrong-module/sibling':5,'support-folder':1,'note-path/invented':1})],
 '5967': [X(**{'support-folder':4}), X(**{'support-folder':3,'note-path/invented':1}), X(**{'support-folder':5,'note-path/invented':1})],
 '6086': [X(**{'support-folder':1,'note-path/invented':1}), X(**{'support-folder':3,'broad-parent':1,'wrong-module/sibling':3,'note-path/invented':1}), X(**{'support-folder':6,'broad-parent':1,'wrong-module/sibling':2})],
 '6141': [X(**{'wrong-module/sibling':6,'broad-parent':7,'note-path/invented':2,'support-folder':4}),
          X(**{'wrong-module/sibling':3,'broad-parent':7,'support-folder':3}),
          X(**{'wrong-module/sibling':7,'broad-parent':9,'support-folder':3})],
 '6292': [X(**{'support-folder':1}), X(**{'note-path/invented':1,'support-folder':2}), X(**{'support-folder':1})],
 '6404': [X(), X(), X(**{'wrong-module/sibling':2})],
 '6406': [X(**{'wrong-module/sibling':1}), X(**{'wrong-module/sibling':2}), X()],
}
XB = {  # bare
 '438': [X(other=1), X(other=2), X(other=1)],
 '3571': [X(other=8, **{'support-folder':2}), X(other=9), X(other=7, **{'support-folder':1})],
 '5164': [X(other=1, **{'wrong-module/sibling':2}), X(other=1, **{'wrong-module/sibling':2,'support-folder':3}), X(other=1, **{'wrong-module/sibling':2,'support-folder':1})],
 '5948': [X(**{'wrong-module/sibling':5,'support-folder':3}), X(**{'wrong-module/sibling':5,'support-folder':4,'other':1}), X(**{'wrong-module/sibling':4})],
 '5967': [X(**{'support-folder':5}), X(**{'support-folder':5}), X(**{'support-folder':7})],
 '6086': [X(**{'support-folder':8}), X(**{'support-folder':5}), X(**{'support-folder':9})],
 '6141': [X(**{'wrong-module/sibling':11,'broad-parent':6,'support-folder':28}), X(**{'wrong-module/sibling':6,'broad-parent':7,'support-folder':25}),
          X(**{'wrong-module/sibling':7,'broad-parent':4,'support-folder':11})],
 '6292': [X(**{'wrong-module/sibling':3,'support-folder':12}), X(**{'wrong-module/sibling':2,'support-folder':3}), X(**{'wrong-module/sibling':2,'support-folder':3})],
 '6404': [X(), X(**{'wrong-module/sibling':1,'support-folder':1}), X()],
 '6406': [X(**{'wrong-module/sibling':1})]*3,
}
# P==1 runs: answer folder count A taken from the per-case report
A_EXTRA = {('6404',0):4, ('6404',1):4, ('6406',2):3}

def runinfo(m, case, arm, i):
    miss = m['missed']; ne = len(m['extra']); R = m['recall']; Pn = m['precision']
    T = round(len(miss) / (1 - R)) if R < 1 else None
    if Pn < 1: A = round(ne / (1 - Pn))
    else:
        A = A_EXTRA.get((case, i))
        if A is None: raise Exception(('A unknown', case, arm, i))
    return dict(miss=miss, ne=ne, R=R, P=Pn, T=T, A=A, C=A - ne)

def f1(p, r): return 0 if p + r == 0 else 2 * p * r / (p + r)

cases = sorted(raw)
plug = {}; bare = {}
for c in cases:
    plug[c] = [runinfo(m, c, 'P', i) for i, m in enumerate(raw[c]['plugin'])]
    bare[c] = [runinfo(m, c, 'B', i) for i, m in enumerate(raw[c]['bare_all'][0][1])]
    for arm, runs, XX in (('P', plug[c], XP), ('B', bare[c], XB)):
        for i, r in enumerate(runs):
            assert sum(XX[c][i].values()) == r['ne'], (c, arm, i, XX[c][i], r['ne'])
    for r in plug[c]:
        pass
# labels
for c in cases:
    for i, r in enumerate(plug[c]):
        r['lab'] = {f: plabel(c, f, i) for f in r['miss']}
# static label for bare
static = {}
for c in cases:
    d = collections.defaultdict(list)
    for i, r in enumerate(plug[c]):
        for f, l in r['lab'].items(): d[f].append(l)
    static[c] = {f: collections.Counter(v).most_common(1)[0][0] for f, v in d.items()}
defaulted = []
for c in cases:
    for i, r in enumerate(bare[c]):
        r['lab'] = {}
        for f in r['miss']:
            if f in static[c]: r['lab'][f] = static[c][f]
            else:
                f2 = short(f)
                l = 'not-in-context' if f2.startswith('main/assets/') else 'usage-hop'
                r['lab'][f] = l; defaulted.append((c, f2, l))

# ---- Table 1 ----
def count(runs_by_case):
    tot = collections.Counter(); cs = collections.defaultdict(set)
    for c, runs in runs_by_case.items():
        for r in runs:
            for f, l in r['lab'].items(): tot[l] += 1; cs[l].add(c)
    return tot, cs
pt, pcs = count(plug); bt, bcs = count(bare)
print('TABLE1 misses'); print('cause | plugin | bare | cases(plugin) | cases(bare)')
for l in MC: print(l, pt[l], bt[l], len(pcs[l]), len(bcs[l]), sorted(pcs[l]))
print('total', sum(pt.values()), sum(bt.values()))
# extras
def xcount(XX):
    t = collections.Counter(); cs = collections.defaultdict(set)
    for c in cases:
        for d in XX[c]:
            for k, v in d.items(): t[k] += v; cs[k].add(c)
    return t, cs
px, pxc = xcount(XP); bx, bxc = xcount(XB)
print('TABLE2 extras');
for k in XC: print(k, px[k], bx[k], len(pxc[k]), len(bxc[k]))
print('total', sum(px.values()), sum(bx.values()))

# ---- baseline reproduce ----
def suite(runs_by_case, mod=None):
    Rs = []; Ps = []; Fs = []
    for c in cases:
        rr = []; pp = []; ff = []
        for i, r in enumerate(runs_by_case[c]):
            R, Pn = (r['R'], r['P']) if mod is None else mod(c, i, r)
            rr.append(R); pp.append(Pn); ff.append(f1(Pn, R))
        Rs.append(sum(rr) / 3); Ps.append(sum(pp) / 3); Fs.append(sum(ff) / 3)
    return sum(Rs) / 10, sum(Ps) / 10, sum(Fs) / 10, Fs
print('plugin base', suite(plug)[:3]); print('bare base', suite(bare)[:3])
# F1 of recorded values for check
# ---- upper bounds ----
def fix_misses(cause):
    def mod(c, i, r):
        k = sum(1 for l in r['lab'].values() if l == cause)
        T = r['T'] if r['T'] else None
        if k == 0: return r['R'], r['P']
        override = None
        if c == '6141' and i == 0 and cause == 'path-prefix': k = 11  # stripping src/app/ also credits the 9 children of the REBA effort-detail/shared parents the run already named
        R = min(1, r['R'] + k / T)
        A, C = r['A'], r['C']
        removed = 0
        if cause == 'parent-not-child':
            removed = min(XP[c][i].get('broad-parent', 0), k)
        A2 = A - removed + k; C2 = C + k
        if cause == 'path-prefix':
            rm = XP[c][i].get('note-path/invented', 0)
            A2 -= rm
        return R, C2 / A2
    return mod
def fix_extras(cause):
    def mod(c, i, r):
        k = XP[c][i].get(cause, 0)
        if k == 0: return r['R'], r['P']
        return r['R'], r['C'] / (r['A'] - k)
    return mod
print('UPPER BOUNDS (plugin, one cause fixed)')
res = {}
for l in MC:
    if l == 'wrong-module': continue
    res[l] = suite(plug, fix_misses(l))[:3]; print('miss', l, [round(x, 3) for x in res[l]])
for l in XC:
    res['x:' + l] = suite(plug, fix_extras(l))[:3]; print('extra', l, [round(x, 3) for x in res['x:' + l]])
# all misses fixed / all extras removed
def all_misses(c, i, r):
    k = len(r['miss']); return 1.0, (r['C'] + k) / (r['A'] + k)
def all_extras(c, i, r): return r['R'], 1.0 if r['A'] - r['ne'] > 0 else 0.0
def all_extras2(c, i, r):
    return r['R'], (1.0 if r['C'] > 0 else 0.0)
print('all misses fixed', [round(x, 3) for x in suite(plug, all_misses)[:3]])
print('all extras removed', [round(x, 3) for x in suite(plug, all_extras2)[:3]])
# fix both miss+extras? combos
def combo(causes_m, causes_x):
    def mod(c, i, r):
        R, Pn = r['R'], r['P']
        return R, Pn
    return mod

# ---- both-miss ----
print('BOTH-MISS by cause: plugin miss instances; bare missed folder in 3/3, 1-2/3, 0/3 runs')
bm = collections.defaultdict(lambda: [0, 0, 0, 0.0])
for c in cases:
    bmiss = collections.Counter(f for r in bare[c] for f in r['miss'])
    for i, r in enumerate(plug[c]):
        for f, l in r['lab'].items():
            n = bmiss.get(f, 0)
            idx = 0 if n == 3 else (2 if n == 0 else 1)
            bm[l][idx] += 1; bm[l][3] += n / 3
for l in MC:
    v = bm[l]; print(l, 'both3/3', v[0], 'partial', v[1], 'bare-found3/3', v[2], 'expected both-miss %.1f of %d' % (v[3], sum(v[:3])))
# reverse: bare misses plugin found
print('bare-only misses (plugin found) total instances:')
cnt = 0
for c in cases:
    pm = collections.Counter(f for r in plug[c] for f in r['miss'])
    for r in bare[c]:
        for f in r['miss']:
            if pm.get(f, 0) == 0: cnt += 1
print(cnt)
print('defaulted bare labels', collections.Counter(defaulted))
# per-case plugin vs bare F1
pf = suite(plug)[3]; bf = suite(bare)[3]
for c, a, b in zip(cases, pf, bf): print(c, round(a, 3), round(b, 3))
json.dump({'res': res}, open('/tmp/nav/res.json', 'w'))

