import { DestroyRef, Directive, HostListener, output, inject } from "@angular/core";
import { takeUntilDestroyed } from "@angular/core/rxjs-interop";
import { MatDialog } from "@angular/material/dialog";
import {
  EmployeeDialogComponent,
  EmployeeDialogData,
} from "components/dialogs/employee-dialog/employee-dialog.component";
import { EmployeeFields } from "models/Employee";

import Employee from "models/Employee";
import { EmployeeFacade } from "state/employee.facade";

@Directive({
  selector: "[appCreateEmployeeButton]",
  standalone: false,
})
export class CreateEmployeeButtonDirective {
  private readonly dialog = inject(MatDialog);
  private readonly employeeFacade = inject(EmployeeFacade);
  private readonly destroyRef = inject(DestroyRef);

  public readonly employeeCreated = output<Employee>();

  @HostListener("click")
  public openCreateEmployeeDialog(): void {
    const dialogRef = this.dialog.open<EmployeeDialogComponent, EmployeeDialogData>(
      EmployeeDialogComponent
    );
    dialogRef
      .afterClosed()
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe((employeeData?: EmployeeFields) => {
        if (employeeData) {
          this.employeeFacade
            .createEmployee$(employeeData)
            .pipe(takeUntilDestroyed(this.destroyRef))
            .subscribe((newEmployee) => {
              this.employeeCreated.emit(newEmployee);
            });
        }
