stamps="11-28-35-774 11-30-02-292 11-31-35-615 11-33-00-362 11-34-43-281 11-36-16-682 11-37-44-927 11-39-48-657 12-05-10-096 12-06-41-631".split()
def load(p):
    L=[json.loads(l) for l in open(p)]
    return L
def msgs(L,sub):
    seen={};order=[]
    for d in L:
        if d['type']!='assistant': continue
        if bool(d.get('agent_id'))!=sub: continue
        m=d['message'];i=m['id']
        if i not in seen: seen[i]={'usage':m['usage'],'calls':[],'text':0};order.append(i)
        for c in m['content']:
            if c['type']=='tool_use': seen[i]['calls'].append(c)
            elif c['type']=='text': seen[i]['text']+=len(c['text'])
            elif c['type']=='thinking': seen[i]['text']+=len(c.get('thinking',''))
        seen[i]['usage']=m['usage']  # last chunk has final output_tokens
    return [seen[i] for i in order]
def results(L,sub):
    r={}
    for d in L:
        if d['type']=='user' and bool(d.get('agent_id'))==sub and isinstance(d['message']['content'],list):
            for x in d['message']['content']:
                if isinstance(x,dict) and x.get('type')=='tool_result':
                    c=x['content']
                    if isinstance(c,list): c=''.join(y.get('text','') for y in c)
                    r[x['tool_use_id']]=len(c)
    return r
def cat(c):
    n=c['name'];i=c['input']
    if n=='Agent' or n=='Task': return 'agent'
    p=i.get('file_path') or i.get('path') or ''
    if n=='Read':
        if p.endswith('context/index.md'): return 'index'
        if '/.ambicode/context/' in p: return 'note'
        return 'src_read'
    if n=='Grep':
        if '.ambicode/context' in p: return 'grep_ctx'
        return 'grep_src_'+i.get('output_mode','files_with_matches')
    return n.lower()
P=dict(i=3,o=15,cr=.3,c5=3.75,c1=6)
def cost(u):
    cc=u.get('cache_creation',{})
    c1=cc.get('ephemeral_1h_input_tokens',0);c5=cc.get('ephemeral_5m_input_tokens',u.get('cache_creation_input_tokens',0)-c1)
    return (u['input_tokens']*P['i']+u['output_tokens']*P['o']+u['cache_read_input_tokens']*P['cr']+c5*P['c5']+c1*P['c1'])/1e6
def tot(ms):
    t=collections.Counter()
    for m in ms:
        u=m['usage'];t['in']+=u['input_tokens'];t['cr']+=u['cache_read_input_tokens'];t['cw']+=u['cache_creation_input_tokens'];t['out']+=u['output_tokens'];t['$']+=cost(u)
    return t
