shall system user users display displayed displays should must when new existing need needs want wants use used using also including include includes applies apply according per via etc ticket description summary acceptance criteria requirements requirement functional scope task tasks item items value values change changes changed update updates updated add added adds remove removed field fields page screen screens page button buttons click clicked text data case cases state states one two three set sets get gets make makes like able allow allows allowed ensure verify test notes note section sections level levels type types name names list lists current default based want expected behavior behaviour result results steps step issue bug feature true false null return files file code repository change anything read need""".split())
def ticket(id):
    p=glob.glob(ROOT+f'navigator/*-{id}-navigator/prompt.md')[0]
    t=open(p).read().split('---',2)[2]
    t=t.split('Do not change anything.')[0]
    return t.strip()
# ---- corpus
EXT=('.ts','.html','.scss','.json')
files={}
for dp,dn,fn in os.walk(BENCH+'main'):
    for f in fn:
        if f.endswith(EXT):
            p=os.path.join(dp,f); rel=os.path.relpath(p,BENCH)
            try: files[rel]=open(p,errors='ignore').read().lower()
            except: pass
N=len(files)
def terms(text):
    T={}  # term -> kind
    for m in re.finditer(r'[“"`‘\']([^”"`’\'\n]{3,60})[”"`’\']',text):
        q=m.group(1).strip()
        if len(q.split())<=6 and re.search(r'[A-Za-z]{3}',q): T[q.lower()]='quote'
    for m in re.finditer(r'\b[a-z]+(?:[A-Z][a-z0-9]+)+\b|\b[A-Z][a-z0-9]+(?:[A-Z][a-z0-9]+)+\b',text): T[m.group(0).lower()]='camel'
    for m in re.finditer(r'\b[A-Za-z][A-Za-z0-9]*(?:[-_.][A-Za-z0-9]+)+\b',text):
        w=m.group(0)
        if re.search(r'[-_]',w) or re.search(r'[a-z]\.[a-z]',w) and w.count('.')>=1 and not w.endswith('.'): T[w.lower()]='ident'
    for m in re.finditer(r'\b[A-Z]{3,}\b',text): T[m.group(0).lower()]='acro'
    for m in re.finditer(r'\b[A-Za-z]{4,}\b',text):
        w=m.group(0).lower()
        if w not in STOP: T.setdefault(w,'word')
    return T
# document frequency via substring on lowercase content (cached)
_df={}
def hits(term):
    if term in _df: return _df[term]
    h=[f for f,c in files.items() if term in c]; _df[term]=h; return h
def gen_a(text,maxdf=0.04,maxterms=60):
    T=terms(text); W={}
    for t,k in T.items():
        h=hits(t)
        if not h or len(h)>maxdf*N: continue
        w=math.log(N/len(h))*(1.5 if k in('quote','camel','ident','acro') else 1.0)
        W[t]=(w,h)
    # keep top terms by weight to bound noise
    top=sorted(W.items(),key=lambda x:-x[1][0])[:maxterms]
    fscore=collections.Counter(); folder=collections.defaultdict(float); fh=collections.defaultdict(collections.Counter)
    for t,(w,h) in top:
        for f in h:
            fscore[f]+=w; fh[os.path.dirname(f)][t]+=1
    for d,c in fh.items():
        folder[d]=sum(min(n,3)*dict(top)[t][0] for t,n in c.items())
    return folder,fscore,[t for t,_ in top]
# ---- notes
def note_lines():
    out=[]  # (kind, folder, linetext)
    for p in glob.glob(CTX+'modules/**/*.md',recursive=True):
        t=open(p).read(); m=re.search(r'^Root:\s*(\S+)',t,re.M)
        if not m: continue
        root=m.group(1).rstrip('/'); sec=None
        for l in t.split('\n'):
            if l.startswith('## '): sec=l[3:].strip(); continue
            mm=re.match(r'- (\S+?)(?: - |$| )',l)
            if sec=='Key files' and mm:
                e=mm.group(1); out.append((root+'/'+os.path.dirname(e) if '/' in e else root,l.lower()))
            elif sec in('Folders','Submodules') and mm and mm.group(1).endswith('/'):
                out.append((root+'/'+mm.group(1).rstrip('/'),l.lower()))
            elif l.strip().startswith('-') or l.startswith('#'):
                out.append((root,l.lower()))
    for l in open(CTX+'index.md'):
        m=re.search(r'\]\(modules/(.*?)(/overview\.md|\.md)\)',l)
        if m: out.append((m.group(1),l.lower()))
    return out
NL=note_lines()
def gen_b(text,maxdf=0.05,maxterms=60):
    T=terms(text); n=len(NL); folder=collections.defaultdict(float)
    W=[]
    for t,k in T.items():
        h=[i for i,(f,l) in enumerate(NL) if t in l]
        if not h or len(h)>maxdf*n: continue
        W.append((math.log(n/len(h))*(1.5 if k!='word' else 1),h,t))
    W.sort(key=lambda x:-x[0])
    fh=collections.defaultdict(collections.Counter)
    for w,h,t in W[:maxterms]:
        for i in h: fh[NL[i][0]][t]+=1; 
    wd={t:w for w,h,t in W}
    for d,c in fh.items(): folder[d]=sum(min(n,3)*wd[t] for t,n in c.items())
    return folder
# ---- import graph
def build_graph():
    imp=collections.defaultdict(set); rev=collections.defaultdict(set)
    for f in files:
        if not f.endswith('.ts') or f.endswith('.spec.ts'): continue
        for m in re.finditer(r'''(?:from|import\(|require\()\s*["']([^"']+)["']''',files[f]):
            s=m.group(1)
            if s.startswith('.'): base=os.path.normpath(os.path.join(os.path.dirname(f),s))
            elif s.split('/')[0] in TOP: base='main/'+s
            else: continue
            for c in (base+'.ts',base+'/index.ts'):
                if c in files: imp[f].add(c); rev[c].add(f); break
    return imp,rev
TOP={d for d in os.listdir(BENCH+'main') if os.path.isdir(BENCH+'main/'+d)}
IMP,REV=build_graph()
def gen_c(text,K=10,hop=0.35):
    folder,fscore,tt=gen_a(text)
    out=collections.defaultdict(float,folder)
    seeds=[f for f,_ in fscore.most_common(K) if f.endswith('.ts') and not f.endswith('.spec.ts')]
    added=collections.defaultdict(float)
    for f in seeds:
        for g in IMP[f]|REV[f]:
            added[os.path.dirname(g)]=max(added[os.path.dirname(g)],hop*fscore[f])
    for d,v in added.items(): out[d]+=v
    return out
def fmt(cands,n):
    return ''.join(f"{d}/\n" for d,_ in sorted(cands.items(),key=lambda x:-x[1])[:n])
