from ev2 import *
U=sorted({os.path.dirname(f) for f in files if f.endswith(('.ts','.html'))})
def under(a): return [d for d in U if d==a or d.startswith(a+'/')]
UC={}
def rollup(leaves,theta,minhit=3,mindepth=3):
    S=set(leaves); anc=set()
    for d in leaves:
        p=d.split('/')
        for k in range(mindepth,len(p)): anc.add('/'.join(p[:k]))
    chosen=[]
    for a in sorted(anc,key=lambda x:x.count('/')):
        if any(a==c or a.startswith(c+'/') for c in chosen): continue
        if a not in UC: UC[a]=len(under(a))
        h=[d for d in S if d==a or d.startswith(a+'/')]
        if len(h)>=minhit and len(h)/UC[a]>=theta: chosen.append(a)
    out=list(chosen)+[d for d in leaves if not any(d==c or d.startswith(c+'/') for c in chosen)]
    return out
if __name__=='__main__':
    C={id:gen_a(ticket(id))[0] for id in IDS}
    for M in (30,60):
      for theta in (None,0.5,0.3,0.2):
        Rs=[];Ps=[];Ns=[];per={}
        for id in IDS:
            t=truth(id); lv=top(C[id],M)
            out=lv if theta is None else rollup(lv,theta)
            s=score(t,[d+'/' for d in out]); Rs.append(s['R']);Ps.append(s['P']);Ns.append(len(out)); per[id]=round(s['R'],2)
        print(M,theta,'R %.3f P %.3f n %.1f'%(avg(Rs),avg(Ps),avg(Ns)),per)
