      const terms = byFolder.get(folderOf(hit)) ?? byFolder.set(folderOf(hit), new Map()).get(folderOf(hit))!;
      const row = terms.get(term) ?? terms.set(term, { weight, files: new Set() }).get(term)!;
      row.files.add(hit);
    }
  }
