    folder,
    score: [...terms.values()].reduce((sum, row) => sum + Math.min(row.files.size, FOLDER_TERM_CAP) * row.weight, 0),
    terms,
  }));
  ranked.sort((a, b) => b.score - a.score || a.folder.localeCompare(b.folder));
  const lines = ranked.slice(0, MAX_FOLDER_LINES).map(({ folder, terms }): FolderLine => ({
    folder,
