/** Files an import specifier can name: exact path, path without extension, or a directory's index/init/mod file. */
class Resolver {
  private readonly exact = new Set<string>();
  private readonly bare = new Map<string, string[]>();
  private readonly suffixes = new Map<string, string[]>();
  constructor(paths: readonly string[]) {
    for (const file of paths) {
      this.exact.add(file);
      const stem = file.slice(0, file.length - path.posix.extname(file).length);
      const keys = [stem];
      if (/(^|\/)(index|__init__|mod|main)$/.test(stem)) keys.push(folderOf(stem));
      for (const key of keys) {
        this.bare.set(key, [...(this.bare.get(key) ?? []), file]);
        const segments = key.split('/');
        for (let at = 0; at < segments.length; at += 1) {
          const suffix = segments.slice(at).join('/');
          this.suffixes.set(suffix, [...(this.suffixes.get(suffix) ?? []), file]);
        }
      }
    }
  }
  private pick(candidates: readonly string[] | undefined, from: string): string | null {
    if (candidates === undefined || candidates.length === 0) return null;
    const ext = path.posix.extname(from);
    return candidates.find((candidate) => candidate.endsWith(ext)) ?? candidates[0]!;
  }
  resolve(from: string, specifier: string): string | null {
    if (specifier.startsWith('.')) {
      const base = path.posix.normalize(path.posix.join(folderOf(from), specifier));
      if (this.exact.has(base)) return base;
      const stem = base.slice(0, base.length - path.posix.extname(base).length);
      return this.pick(this.bare.get(base), from) ?? this.pick(this.bare.get(stem), from);
    }
    if (!specifier.includes('/')) return null;
    const unique = this.suffixes.get(specifier.replace(/^[@~#$]+\/?/, ''));
    return unique !== undefined && new Set(unique).size === 1 ? unique[0]! : null;
  }
