import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { routeFixture, type RouteFixture } from '#testing/fixtures/route-fixture';
import { folderCandidates, nearFolders, importEdges, ticketTerms, MAX_FOLDER_LINES, MAX_NEAR_LINES } from './folders.ts';

const project = { id: 'app', root: '.', paths: [], ecosystem: { languages: [], frameworks: [], packageManager: null }, include: [], exclude: [], commands: {}, packs: [], checks: {}, policyFiles: [] } as never;

async function repo(extra: Record<string, string> = {}): Promise<RouteFixture> {
  const fx = await routeFixture({ routes: {} });
  const files: Record<string, string> = {
    'src/upload/upload-page.ts': 'import { check } from "../shared/check";\nexport const label = "all assessments";\nexport function redirectAfterUpload() { return check(); }\n',
    'src/upload/upload-form.ts': 'export const hint = "all assessments";\n',
    'src/upload/helpers.ts': 'export const x = 1;\n',
    'src/shared/check.ts': 'export function check() { return 1; }\n',
    'src/shared/index.ts': 'export * from "./check";\n',
    'src/billing/ledger.py': 'from ..shared import thing\nfrom .totals import total\n',
    'src/billing/totals.py': 'total = 1\n',
    'src/api/client.ts': 'import { check } from "shared/check";\nimport { thing } from "lodash/fp";\nconst a = require("../upload/upload-form");\n',
    ...Object.fromEntries(Array.from({ length: 60 }, (_, index) => [`src/other/unrelated-${index}.ts`, `export const value${index} = ${index}; // common\n`])),
    ...extra,
  };
  for (const [file, content] of Object.entries(files)) await fx.repo.write(file, content);
  await fx.repo.commitAll('files');
  return fx;
}

describe('map --folders', () => {
  it('extracts quoted strings, identifiers, acronyms and non-stop words', () => {
    const terms = ticketTerms('When the "all assessments" list shows `redirectAfterUpload` or kebab-case, snake_case and the CVR badge, we need Tooltips');
    assert.equal(terms.get('all assessments'), 'quote');
    assert.equal(terms.get('redirectafterupload'), 'camel');
    assert.equal(terms.get('kebab-case'), 'ident');
    assert.equal(terms.get('snake_case'), 'ident');
    assert.equal(terms.get('cvr'), 'acro');
    assert.equal(terms.get('tooltips'), 'word');
    assert.ok(!terms.has('when') && !terms.has('need'));
  });

  it('ranks folders by summed term weight and reports hit files, folder size and the top terms', async () => {
    const fx = await repo();
    try {
      const found = await folderCandidates(fx.runtime, project, 'The "all assessments" label and redirectAfterUpload');
      assert.equal(found.lines[0]!.folder, 'src/upload');
      assert.equal(found.text.split('\n')[0], 'src/upload/ - 2/3 files; all assessments, redirectafterupload');
    } finally {
      await fx.dispose();
    }
  });

  it('drops a term found in more than 4% of the files', async () => {
    const fx = await repo();
    try {
      const found = await folderCandidates(fx.runtime, project, 'common export "all assessments"');
      assert.ok(!found.terms.includes('common') && !found.terms.includes('export'), found.terms.join(','));
      assert.ok(found.terms.includes('all assessments'));
    } finally {
      await fx.dispose();
    }
  });

  it('prints at most 20 lines', async () => {
    const files = Object.fromEntries(Array.from({ length: 30 }, (_, index) => [`src/pkg${index}/mod.ts`, 'export const zebraStripe = 1;\n']));
    const fx = await repo(files);
    try {
      const found = await folderCandidates(fx.runtime, project, 'zebraStripe');
      assert.equal(found.lines.length, MAX_FOLDER_LINES);
      assert.equal(found.text.split('\n').length, MAX_FOLDER_LINES);
    } finally {
      await fx.dispose();
    }
  });
});

describe('map --near', () => {
  it('resolves relative, dotted, extension-less, index and suffix specifiers and ignores packages', async () => {
    const fx = await repo();
    try {
      const names = ['src/api/client.ts', 'src/upload/upload-page.ts', 'src/upload/upload-form.ts', 'src/shared/check.ts', 'src/shared/index.ts', 'src/billing/ledger.py', 'src/billing/totals.py'];
      const edges = importEdges(await Promise.all(names.map(async (path) => ({ path, content: await fx.runtime.fs.readText(`${fx.repo.root}/${path}`) }))));
      const has = (from: string, to: string) => edges.some(([a, b]) => a === from && b === to);
      assert.ok(has('src/upload/upload-page.ts', 'src/shared/check.ts'), 'relative');
      assert.ok(has('src/api/client.ts', 'src/shared/check.ts'), 'suffix of a non-relative path');
      assert.ok(has('src/api/client.ts', 'src/upload/upload-form.ts'), 'require');
      assert.ok(has('src/shared/index.ts', 'src/shared/check.ts'), './check');
      assert.ok(has('src/billing/ledger.py', 'src/billing/totals.py'), 'python .totals');
      assert.ok(has('src/billing/ledger.py', 'src/shared/index.ts'), 'python ..shared resolves to the folder index');
      assert.ok(!edges.some(([, to]) => to.includes('lodash')));
    } finally {
      await fx.dispose();
    }
  });

  it('lists neighbours in both directions by edge count and leaves out the given folders', async () => {
    const fx = await repo();
    try {
      const near = await nearFolders(fx.runtime, project, ['src/upload/']);
      assert.deepEqual(near.lines.map((line) => line.folder), ['src/api', 'src/shared']);
      assert.equal(near.text.split('\n')[0], 'src/api/ - 1/1 files; imports given 1');
      assert.equal(near.lines[1]!.reason, 'imported by given 1');
      assert.ok(!near.lines.some((line) => line.folder === 'src/upload'));
    } finally {
      await fx.dispose();
    }
  });

  it('prints at most 10 folders', async () => {
    const extra = Object.fromEntries(Array.from({ length: 15 }, (_, index) => [`src/dep${index}/m.ts`, 'import "../upload/helpers";\n']));
    const fx = await repo(extra);
    try {
      assert.equal(MAX_NEAR_LINES, (await nearFolders(fx.runtime, project, ['src/upload'])).lines.length);
    } finally {
      await fx.dispose();
    }
  });
});
