import path from 'node:path';
import { openWorkspace } from '#modules/config/workspace';
import type { ProjectConfig } from '#types/modules/config';
import { literalPathspec } from '#platform/git/git';
import { matchesAnyGlob } from '#util/glob';
import { normalizeRelative, toProjectRelative } from '#util/paths';
import { isTestPath, pathExclusionReason } from '#util/path-classes';
import type { Runtime } from '#types/composition';
import { STOPWORDS } from './map.ts';

/** Offline grid on 10 navigator cases: a term in more than 4% of files names the project, not a place. */
const MAX_DOCUMENT_FREQUENCY = 0.04;
/** Same grid: 60 weighted terms bounded the noise; more terms lowered top-20 recall. */
const MAX_FOLDER_TERMS = 60;
/** Same grid: 20 lines is top-20 recall 0.435 against a ceiling of 0.706, in about 450 tokens. */
export const MAX_FOLDER_LINES = 20;
/** Same grid: ten neighbours kept the near list as short as the answer it extends. */
export const MAX_NEAR_LINES = 10;
const MATCHES_PER_LINE = 3;
/** A term repeated in many files of one folder adds three times at most, so one broad folder cannot outscore a dense one. */
const FOLDER_TERM_CAP = 3;
/** Words the offline grid showed carrying no place in a ticket. */
const TICKET_WORDS = new Set(`about above after again all also and any are because been before being below between both but can could did does doing down during each few for from further had has have having her here hers him his how into its just more most nor not now off once only other our out over own same she should some such than that the their them then there these they this those through too under until very was were what when where which while who whom why will with would you your
shall system user users display displayed displays must new existing need needs want wants use used using including include includes applies apply according per via etc ticket description summary acceptance criteria requirements requirement functional scope task tasks item items value values change changes changed update updates updated add added adds remove removed field fields page screen screens button buttons click clicked text data case cases state states one two three set sets get gets make makes like able allow allows allowed ensure verify test notes note section sections level levels type types name names list lists current default based expected behavior behaviour result results steps step issue bug feature true false null return files file code repository anything read`.split(/\s+/));

type Kind = 'quote' | 'camel' | 'ident' | 'acro' | 'word';

/** Quoted strings, camelCase, kebab/snake/dotted identifiers and acronyms keyed by lowercase form; a later kind replaces an earlier one, plain words only fill gaps. */
export function ticketTerms(text: string): Map<string, Kind> {
  const found = new Map<string, Kind>();
  for (const match of text.matchAll(/[“"`‘']([^”"`’'\n]{3,60})[”"`’']/g)) {
    const quoted = match[1]!.trim();
    if (quoted.split(/\s+/).length <= 6 && /[A-Za-z]{3}/.test(quoted)) found.set(quoted.toLowerCase(), 'quote');
  }
  for (const match of text.matchAll(/\b[a-z]+(?:[A-Z][a-z0-9]+)+\b|\b[A-Z][a-z0-9]+(?:[A-Z][a-z0-9]+)+\b/g)) found.set(match[0].toLowerCase(), 'camel');
  for (const match of text.matchAll(/\b[A-Za-z][A-Za-z0-9]*(?:[-_.][A-Za-z0-9]+)+\b/g)) {
    if (/[-_]/.test(match[0]) || /[a-z]\./.test(match[0])) found.set(match[0].toLowerCase(), 'ident');
  }
  for (const match of text.matchAll(/\b[A-Z]{3,}\b/g)) found.set(match[0].toLowerCase(), 'acro');
  for (const match of text.matchAll(/\b[A-Za-z]{4,}\b/g)) {
    const word = match[0].toLowerCase();
    if (!TICKET_WORDS.has(word) && !STOPWORDS.has(word) && !found.has(word)) found.set(word, 'word');
  }
  return found;
}

export interface FolderLine { folder: string; hit: number; total: number; reason: string }
export interface FolderMap { lines: FolderLine[]; text: string; terms: string[] }

interface IndexedFile { path: string; content: string }

const folderOf = (file: string): string => path.posix.dirname(file);
const label = (folder: string): string => (folder === '.' ? './' : `${folder}/`);
const render = (lines: readonly FolderLine[]): string => lines.map((line) => `${label(line.folder)} - ${line.hit}/${line.total} files; ${line.reason}`).join('\n');

/** Every tracked or untracked-unignored text file the project config admits, with lowercase content for term search. */
async function indexFiles(runtime: Runtime, project: ProjectConfig): Promise<IndexedFile[]> {
  const { git, repositoryRoot } = await openWorkspace(runtime);
  const root = normalizeRelative(project.root);
  const listed = (await git.listFiles(root === '' ? null : literalPathspec(root))).filter((file) => {
    const relative = toProjectRelative(root, file) ?? file;
    return pathExclusionReason(file) === null && (project.include.length === 0 || matchesAnyGlob(relative, project.include)) && !matchesAnyGlob(relative, project.exclude);
  });
  const files: IndexedFile[] = [];
  for (let at = 0; at < listed.length; at += 64) {
    const batch = await Promise.all(listed.slice(at, at + 64).map(async (file) => {
      try { return { path: file, content: await runtime.fs.readText(path.join(repositoryRoot, file)) }; } catch { return null; }
    }));
    for (const entry of batch) if (entry !== null && !entry.content.includes('\0')) files.push(entry);
  }
  return files;
}

export async function folderCandidates(runtime: Runtime, project: ProjectConfig, ticket: string): Promise<FolderMap> {
  const files = (await indexFiles(runtime, project)).map((file) => ({ path: file.path, content: file.content.toLowerCase() }));
  const perFolder = new Map<string, number>();
  for (const file of files) perFolder.set(folderOf(file.path), (perFolder.get(folderOf(file.path)) ?? 0) + 1);
  const weighted: { term: string; weight: number; hits: string[] }[] = [];
  for (const [term, kind] of ticketTerms(ticket)) {
    const hits = files.filter((file) => file.content.includes(term)).map((file) => file.path);
    if (hits.length === 0 || hits.length > MAX_DOCUMENT_FREQUENCY * files.length) continue;
    weighted.push({ term, hits, weight: Math.log(files.length / hits.length) * (kind === 'word' ? 1 : 1.5) });
  }
  const top = weighted.sort((a, b) => b.weight - a.weight).slice(0, MAX_FOLDER_TERMS);
  const byFolder = new Map<string, Map<string, { weight: number; files: Set<string> }>>();
  for (const { term, weight, hits } of top) {
    for (const hit of hits) {
      const terms = byFolder.get(folderOf(hit)) ?? byFolder.set(folderOf(hit), new Map()).get(folderOf(hit))!;
      const row = terms.get(term) ?? terms.set(term, { weight, files: new Set() }).get(term)!;
      row.files.add(hit);
    }
  }
  const ranked = [...byFolder].map(([folder, terms]) => ({
    folder,
    score: [...terms.values()].reduce((sum, row) => sum + Math.min(row.files.size, FOLDER_TERM_CAP) * row.weight, 0),
    terms,
  }));
  ranked.sort((a, b) => b.score - a.score || a.folder.localeCompare(b.folder));
  const lines = ranked.slice(0, MAX_FOLDER_LINES).map(({ folder, terms }): FolderLine => ({
    folder,
    hit: new Set([...terms.values()].flatMap((row) => [...row.files])).size,
    total: perFolder.get(folder) ?? 0,
    reason: [...terms].sort((a, b) => b[1].weight - a[1].weight).slice(0, MATCHES_PER_LINE).map(([term]) => term).join(', '),
  }));
  return { lines, text: render(lines), terms: top.map((row) => row.term) };
}

const QUOTED_SPECIFIER = /(?:\bfrom|\bimport|\brequire(?:_once)?|\binclude|@import|\bsource)\s*\(?\s*["']([^"'\n]+)["']/g;
/** `from ..pkg.mod import x`: dots climb directories, the rest is a dotted path. */
const DOTTED_RELATIVE = /^[ \t]*from\s+(\.+)([\w.]*)\s+import\b/gm;

/** Files an import specifier can name: exact path, path without extension, or a directory's index/init/mod file. */
class Resolver {
  private readonly exact = new Set<string>();
  private readonly bare = new Map<string, string[]>();
  private readonly suffixes = new Map<string, string[]>();
  constructor(paths: readonly string[]) {
    for (const file of paths) {
      this.exact.add(file);
      const stem = file.slice(0, file.length - path.posix.extname(file).length);
      const keys = [stem];
      if (/(^|\/)(index|__init__|mod|main)$/.test(stem)) keys.push(folderOf(stem));
      for (const key of keys) {
        this.bare.set(key, [...(this.bare.get(key) ?? []), file]);
        const segments = key.split('/');
        for (let at = 0; at < segments.length; at += 1) {
          const suffix = segments.slice(at).join('/');
          this.suffixes.set(suffix, [...(this.suffixes.get(suffix) ?? []), file]);
        }
      }
    }
  }
  private pick(candidates: readonly string[] | undefined, from: string): string | null {
    if (candidates === undefined || candidates.length === 0) return null;
    const ext = path.posix.extname(from);
    return candidates.find((candidate) => candidate.endsWith(ext)) ?? candidates[0]!;
  }
  resolve(from: string, specifier: string): string | null {
    if (specifier.startsWith('.')) {
      const base = path.posix.normalize(path.posix.join(folderOf(from), specifier));
      if (this.exact.has(base)) return base;
      const stem = base.slice(0, base.length - path.posix.extname(base).length);
      return this.pick(this.bare.get(base), from) ?? this.pick(this.bare.get(stem), from);
    }
    if (!specifier.includes('/')) return null;
    const unique = this.suffixes.get(specifier.replace(/^[@~#$]+\/?/, ''));
    return unique !== undefined && new Set(unique).size === 1 ? unique[0]! : null;
  }
}

/** Import edges between non-test files as [importer, imported] pairs, one per distinct pair. */
export function importEdges(files: readonly IndexedFile[]): [string, string][] {
  const code = files.filter((file) => !isTestPath(file.path));
  const resolver = new Resolver(code.map((file) => file.path));
  const edges = new Map<string, [string, string]>();
  const add = (from: string, to: string | null): void => {
    if (to !== null && to !== from) edges.set(`${from}\0${to}`, [from, to]);
  };
  for (const file of code) {
    for (const match of file.content.matchAll(QUOTED_SPECIFIER)) add(file.path, resolver.resolve(file.path, match[1]!));
    for (const match of file.content.matchAll(DOTTED_RELATIVE)) {
      const up = match[1]!.length - 1;
      add(file.path, resolver.resolve(file.path, `${up === 0 ? './' : '../'.repeat(up)}${match[2]!.replaceAll('.', '/')}`));
    }
  }
  return [...edges.values()];
}

export async function nearFolders(runtime: Runtime, project: ProjectConfig, given: readonly string[]): Promise<FolderMap> {
  const files = await indexFiles(runtime, project);
  const inputs = new Set(given.map((folder) => normalizeRelative(folder).replace(/\/+$/, '') || '.'));
  const perFolder = new Map<string, number>();
  for (const file of files) perFolder.set(folderOf(file.path), (perFolder.get(folderOf(file.path)) ?? 0) + 1);
  const found = new Map<string, { imports: number; importedBy: number; files: Set<string> }>();
  const note = (folder: string, file: string, direction: 'imports' | 'importedBy'): void => {
    const row = found.get(folder) ?? found.set(folder, { imports: 0, importedBy: 0, files: new Set() }).get(folder)!;
    row[direction] += 1;
    row.files.add(file);
  };
  for (const [from, to] of importEdges(files)) {
    const fromIn = inputs.has(folderOf(from));
    const toIn = inputs.has(folderOf(to));
    if (fromIn && !toIn) note(folderOf(to), to, 'importedBy');
    else if (toIn && !fromIn) note(folderOf(from), from, 'imports');
  }
  const ranked = [...found].sort((a, b) => b[1].imports + b[1].importedBy - (a[1].imports + a[1].importedBy) || a[0].localeCompare(b[0]));
  const lines = ranked.slice(0, MAX_NEAR_LINES).map(([folder, row]): FolderLine => ({
    folder, hit: row.files.size, total: perFolder.get(folder) ?? 0,
    reason: [row.imports > 0 ? `imports given ${row.imports}` : '', row.importedBy > 0 ? `imported by given ${row.importedBy}` : ''].filter((part) => part !== '').join(', '),
  }));
  return { lines, text: render(lines), terms: [] };
}
