shall system user users display displayed displays should must when new existing need needs want wants use used using also including include includes applies apply according per via etc ticket description summary acceptance criteria requirements requirement functional scope task tasks item items value values change changes changed update updates updated add added adds remove removed field fields page screen screens page button buttons click clicked text data case cases state states one two three set sets get gets make makes like able allow allows allowed ensure verify test notes note section sections level levels type types name names list lists current default based want expected behavior behaviour result results steps step issue bug feature true false null return files file code repository change anything read need""".split())
def ticket(id):
    p=glob.glob(ROOT+f'navigator/*-{id}-navigator/prompt.md')[0]
    t=open(p).read().split('---',2)[2]
    t=t.split('Do not change anything.')[0]
    return t.strip()
# ---- corpus
EXT=('.ts','.html','.scss','.json')
files={}
for dp,dn,fn in os.walk(BENCH+'main'):
    for f in fn:
        if f.endswith(EXT):
            p=os.path.join(dp,f); rel=os.path.relpath(p,BENCH)
            try: files[rel]=open(p,errors='ignore').read().lower()
            except: pass
N=len(files)
def terms(text):
    T={}  # term -> kind
    for m in re.finditer(r'[“"`‘\']([^”"`’\'\n]{3,60})[”"`’\']',text):
        q=m.group(1).strip()
        if len(q.split())<=6 and re.search(r'[A-Za-z]{3}',q): T[q.lower()]='quote'
    for m in re.finditer(r'\b[a-z]+(?:[A-Z][a-z0-9]+)+\b|\b[A-Z][a-z0-9]+(?:[A-Z][a-z0-9]+)+\b',text): T[m.group(0).lower()]='camel'
    for m in re.finditer(r'\b[A-Za-z][A-Za-z0-9]*(?:[-_.][A-Za-z0-9]+)+\b',text):
        w=m.group(0)
        if re.search(r'[-_]',w) or re.search(r'[a-z]\.[a-z]',w) and w.count('.')>=1 and not w.endswith('.'): T[w.lower()]='ident'
    for m in re.finditer(r'\b[A-Z]{3,}\b',text): T[m.group(0).lower()]='acro'
    for m in re.finditer(r'\b[A-Za-z]{4,}\b',text):
        w=m.group(0).lower()
        if w not in STOP: T.setdefault(w,'word')
    return T
# document frequency via substring on lowercase content (cached)
_df={}
def hits(term):
    if term in _df: return _df[term]
    h=[f for f,c in files.items() if term in c]; _df[term]=h; return h
def gen_a(text,maxdf=0.04,maxterms=60):
    T=terms(text); W={}
