import { readFileSync, readdirSync } from 'node:fs';
import { navigatorTruth, navigatorMetrics, truthFolders } from '/Users/KillBill/Documents/projects/mine/ai/ambicode/evals/scripts/navigator-cases.mjs';
import { events } from '/Users/KillBill/Documents/projects/mine/ai/ambicode/evals/scripts/trace.mjs';
import { foundPaths, finalTextOf } from '/Users/KillBill/Documents/projects/mine/ai/ambicode/evals/scripts/metrics.mjs';

const R = '/Users/KillBill/Documents/projects/mine/ai/ambicode/evals/cases/results';
const runs = [['fe-vs-6141-navigator', '2026-10-20T15-31-14-135Z'], ['fe-vs-3571-navigator', '2026-10-20T15-34-48-144Z'], ['fe-vs-6404-navigator', '2026-10-20T15-37-11-229Z']];
const mean = (a) => a.reduce((x, y) => x + y, 0) / a.length;
for (const [name, stamp] of runs) {
  const truth = navigatorTruth(name);
  const agg = JSON.parse(readFileSync(`${R}/${stamp}/aggregate-result.json`));
  const costs = agg.cases[0].arms.with.map((r) => r.costUsd);
  const dir = `${R}/traces/plugin/${stamp}`;
  const rows = [];
  for (const f of readdirSync(dir).filter((x) => x.endsWith('.jsonl')).sort()) {
    const text = readFileSync(`${dir}/${f}`, 'utf8');
    const m = navigatorMetrics(truth, text);
    const found = foundPaths(finalTextOf(text), 'files-block');
    let mainBash = 0, subBash = 0, mapCalls = 0, greps = 0, reads = 0, globs = 0;
    const models = new Set();
    for (const e of events(text)) {
      if (e.type !== 'assistant') continue;
      const sub = Boolean(e.parent_tool_use_id);
      if (sub) models.add(e.message.model);
      for (const p of e.message?.content ?? []) {
        if (p.type !== 'tool_use') continue;
        if (p.name === 'Bash') {
          if (sub) { subBash++; if (/map\s+--folders/.test(p.input.command)) mapCalls++; } else mainBash++;
        } else if (sub && p.name === 'Grep') greps++;
        else if (sub && p.name === 'Read') reads++;
        else if (sub && p.name === 'Glob') globs++;
      }
    }
    rows.push({ f, R: m.recall, P: m.precision, F1: m.f1, folders: found ? truthFolders(found).length : null, paths: found?.length, mainBash, subBash, mapCalls, greps, reads, globs, models: [...models].join() });
  }
  console.log(`# ${name} ${stamp} cost/run=${mean(costs).toFixed(3)} (${costs.map((c) => c.toFixed(3))})`);
  console.table(rows);
  console.log('mean R', mean(rows.map((r) => r.R ?? 0)).toFixed(3), 'P', mean(rows.map((r) => r.P ?? 0)).toFixed(3), 'F1', mean(rows.map((r) => r.F1 ?? 0)).toFixed(3), 'aggScore', agg.cases[0].aggregates.score);
}

