const {scoreNavigator,navigatorTruth,truthFolders}=await import(R+'/scripts/navigator-cases.mjs');
const {finalTextOf,foundPaths}=await import(R+'/scripts/metrics.mjs');
const G={
 SON:['11-30-02-292','11-37-44-927','12-05-10-096','12-59-15-203','13-01-01-572','13-02-31-241','13-36-23-118','13-38-20-659','13-39-49-826'],
 HORIG:['13-05-50-753','13-07-19-027','13-09-18-582','13-10-58-190'],
 HTRIM:['13-54-52-887','13-57-04-450','13-59-08-410'],
 H634:['14-10-18-208','14-12-18-013','14-14-22-629'],
 H1D6:['14-27-43-277','14-29-42-079','14-31-16-567'],
};
const CASES=['6141','3571','6404'];
const strip=s=>String(s).replace(/\/private\/tmp\/[^/]+\/home\/cwd\/?/,'');
function cls(c){const i=c.input;
 if(c.name==='Read'){const p=strip(i.file_path); return p.endsWith('context/index.md')?'idx':p.includes('.ambicode')?'note':'src';}
 if(c.name==='Grep'){const p=strip(i.path||''); return p.includes('.ambicode')?'ctx':'gsrc';}
 return c.name==='Glob'?'glob':c.name;}
function noteSet(b,k){const S=new Set();const body=b.replace(/^\s*\d+\t/gm,'');
 if(k==='idx'){for(const m of body.matchAll(/\]\(modules\/([^)]+?)(?:\/overview)?\.md\)/g)) S.add(m[1]); return S;}
 const root=(body.match(/^Root: (.+)$/m)||[])[1]; if(!root) return S; S.add(root);
 const sec=n=>{const m=body.match(new RegExp('## '+n+'\\n([\\s\\S]*?)(?:\\n## |$)'));return m?m[1]:''};
 for(const l of sec('Folders').split('\n')){const m=l.match(/^- ([^ ]+?)\/? - /)||l.match(/^- ([^ ]+?)\/?$/); if(m) S.add(root+'/'+m[1].replace(/\/$/,''));}
 for(const l of sec('Key files').split('\n')){const m=l.match(/^- ([^ ]+) - /); if(m&&m[1].includes('/')) S.add(root+'/'+m[1].replace(/\/[^/]+$/,''));}
 for(const l of sec('Submodules').split('\n')){const m=l.match(/^- ([^ ]+?)(?:\/overview)?\.md - /); if(m) S.add(root+'/'+m[1].replace(/\/overview$/,'').replace(/\.md$/,'')) }
 return S;}
const runs=[];
for(const [g,sts] of Object.entries(G)) for(const st of sts){
 const dir=T+st+'Z/'; if(!fs.existsSync(dir)) {console.error('missing',dir);continue;}
 for(const f of fs.readdirSync(dir).filter(x=>x.endsWith('.jsonl'))){
  const m=f.match(/fe-vs-(\d+)-navigator-(\d+)/); if(!m||!CASES.includes(m[1])) continue;
  const txt=fs.readFileSync(dir+f,'utf8'); const L=txt.split('\n').filter(Boolean).map(JSON.parse);
  const truth=navigatorTruth('fe-vs-'+m[1]+'-navigator',R); const tf=truthFolders(truth.relevant);
  const calls=[];const idc={};let texts=[];
  const events=[]; // ordered
  for(const l of L){
   if(l.type==='assistant') for(const x of l.message.content){
     if(x.type==='tool_use'&&!['Agent','Task'].includes(x.name)){const k=cls(x);const q=x.name==='Grep'?x.input.pattern+' @'+strip(x.input.path||'.'):x.name==='Glob'?x.input.pattern:strip(x.input.file_path||'');const o={id:x.id,k,q,name:x.name,input:x.input};idc[x.id]=o;calls.push(o);events.push(o);}
     if(x.type==='text') texts.push({after:calls.length,t:x.text});}
   if(l.type==='user'&&Array.isArray(l.message.content)) for(const x of l.message.content) if(x.type==='tool_result'&&idc[x.tool_use_id]){idc[x.tool_use_id].body=typeof x.content==='string'?x.content:JSON.stringify(x.content);}
