  // surfacing
  const surf={};
  calls.forEach((c,i)=>{const b=c.body||''; for(const f2 of tf){ if(surf[f2]!==undefined) continue;
    let hit=false;
    if(c.k==='note'||c.k==='idx'){ if(!c.set) c.set=noteSet(b,c.k); if(c.set.has(f2)) hit=true; }
    else if(c.k==='ctx'||c.k==='gsrc'||c.k==='glob'||c.k==='src'){ if(b.includes(f2+'/')||b.includes(f2.replace(/^main\//,'main/')+'.')||(c.k==='src'&&strip(c.q).startsWith(f2+'/'))) hit=true; }
    if(hit) surf[f2]=i;}});
  const named=new Set(tf.filter(f2=>!sc.missed.includes(f2)));
  // answer shape
  const tset=new Set(tf);
  const allbody=calls.map(c=>c.body||'').join('\n');
  const folders=found.filter(p=>p.endsWith('/')).map(p=>p.slice(0,-1)); const files=found.filter(p=>!p.endsWith('/'));
  const parent=folders.filter(p=>!tset.has(p)&&tf.some(t=>t.startsWith(p+'/')));
  const invented=found.filter(p=>{const s=p.replace(/\/$/,'').split('/').pop(); return !allbody.includes(s);});
  const printedList=texts.some(t=>t.after<=1&&/ \| .* \| /.test(t.t))||texts.some(t=>(t.t.match(/ \| /g)||[]).length>=4);
  runs.push({g,st:st.slice(0,5),case:m[1],run:m[2],calls,sc,surf,named,found,folders,files,parent,invented,printedList,tf,
    cnt:k=>calls.filter(c=>c.k===k).length});
 }}
export {runs,G,CASES};

content.text:
Запустил бесплатный разбор, чтобы проверить твою гипотезу на трейсах.

Сам промпт её поддерживает. В нём пять мест, которые просят сужать, и ни одно не просит сохранять:
- B2 «Pick only sources that are missed and related»;
- B5 «only the subfolders the ticket touches»;
- B6 «Filter the final list. Drop paths…»;
- Answer «confirmed to be related»;
- Answer «Name a folder only when every file inside it belongs».

Sonnet, судя по прошлому разбору, эти фильтры во многом игнорирует. Haiku выполняет их буквально, а степень связи с тикетом не оценивает.

Что проверяю:
1. **Фаза A.** Насколько хорошо haiku выбирает модули по тикету по сравнению с sonnet: precision и recall выбранных модулей относительно модулей, где лежат правильные папки.
2. **Где теряются папки.** Для каждой правильной папки: была ли она в прочитанной заметке, попадалась ли в выводе инструментов, вошла ли в ответ. Для потерянных — на каком шаге: B2/B5, B6/Answer или папку вообще не рассматривали.
3. **То же для лишних папок.** Это покажет, sonnet просто шире или лучше понимает связь с тикетом.
4. **Рассуждения haiku и примеры.** Если в трейсах есть его рассуждения о связи с тикетом, дословные цитаты. Плюс два примера на 6141 и 3571: тикет, строки заметки, что назвал haiku и что sonnet.

Как объяснить это haiku, предложу после разбора. Сейчас вижу один вариант. Заменить фильтры на шкалу связи с тикетом:
- меняется напрямую;
- использует изменяемое;
- однотипный сосед изменяемого;
- не связано.

Выбрасывать только последнее. И дать один короткий общий пример: по памяти, когда haiku выполняет текст наполовину, пример работает лучше прозы.

